    "breaks_where": "В отличие от датасета, геологическая обстановка меняется по разрезу, требуя разветвления логики на разные типы пород."
  },
  "now_practice": [],
  "layers": {
    "mechanism": [
      {
        "text": "Разделение алгоритма сканирования на две ветки обусловлено физическими свойствами вмещающих пород.",
        "claims": [
          "c2",
          "c5",
          "c6"
        ]
      }
    ],
    "practice": [
      {
        "text": "Применение экспресс-метода экономит время при первичном анализе новых скважин.",
        "claims": [
          "c1"
        ]
      }
    ],
    "nuances": [
      {
        "text": "Выявление водных зон критически важно для корректной оценки запасов углеводородов.",
        "claims": [
          "c4"
        ]
      }
