        "claims": [
          "c5"
        ]
      }
    ]
  },
  "glossary": [
    {
      "term": "коллектор",
      "en": "reservoir",
      "definition": "Горная порода, способная вмещать и пропускать флюиды."
    },
    {
      "term": "неколлектор",
      "en": "nonreservoir",
      "definition": "Порода, не обладающая достаточной емкостью или проницаемостью для движения флюидов."
